using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The SDK discovers methods decorated with [McpServerTool] via reflection.
/// Constructor parameters are resolved from DI automatically.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _http;

    // The DI container injects an HttpClient configured via IHttpClientFactory
    public WeatherTools(HttpClient http)
    {
        _http = http;
    }

    [McpServerTool, Description("Get current weather for a city")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'Seattle'")] string city,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";

        var response = await _http.GetFromJsonAsync<WttrResponse>(url, cancellationToken);

        if (response?.CurrentCondition is not [var current, ..])
            return $"No weather data found for '{city}'.";

        return $"""
            Weather for {city}:
              Temperature: {current.TempC}°C / {current.TempF}°F
              Condition:   {current.WeatherDesc?.FirstOrDefault()?.Value ?? "Unknown"}
              Humidity:    {current.Humidity}%
              Wind:        {current.WindspeedKmph} km/h {current.WindDir}
            """;
    }

    [McpServerTool, Description("Get a short weather forecast summary for a city")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of days (1-3)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 3);
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";

        var response = await _http.GetFromJsonAsync<WttrResponse>(url, cancellationToken);

        if (response?.Weather is null or { Count: 0 })
            return $"No forecast data found for '{city}'.";

        var lines = response.Weather.Take(days).Select(w =>
            $"  {w.Date}: {w.MinTempC}-{w.MaxTempC}°C, {w.Hourly?.FirstOrDefault()?.WeatherDesc?.FirstOrDefault()?.Value ?? "N/A"}");

        return $"Forecast for {city}:\n{string.Join('\n', lines)}";
    }
}

// Minimal DTOs for wttr.in JSON response
public sealed class WttrResponse
{
    [JsonPropertyName("current_condition")]
    public List<CurrentCondition>? CurrentCondition { get; set; }

    [JsonPropertyName("weather")]
    public List<WeatherDay>? Weather { get; set; }
}

public sealed class CurrentCondition
{
    [JsonPropertyName("temp_C")] public string? TempC { get; set; }
    [JsonPropertyName("temp_F")] public string? TempF { get; set; }
    [JsonPropertyName("humidity")] public string? Humidity { get; set; }
    [JsonPropertyName("windspeedKmph")] public string? WindspeedKmph { get; set; }
    [JsonPropertyName("winddir16Point")] public string? WindDir { get; set; }
    [JsonPropertyName("weatherDesc")] public List<WeatherDesc>? WeatherDesc { get; set; }
}

public sealed class WeatherDay
{
    [JsonPropertyName("date")] public string? Date { get; set; }
    [JsonPropertyName("mintempC")] public string? MinTempC { get; set; }
    [JsonPropertyName("maxtempC")] public string? MaxTempC { get; set; }
    [JsonPropertyName("hourly")] public List<HourlyEntry>? Hourly { get; set; }
}

public sealed class HourlyEntry
{
    [JsonPropertyName("weatherDesc")] public List<WeatherDesc>? WeatherDesc { get; set; }
}

public sealed class WeatherDesc
{
    [JsonPropertyName("value")] public string? Value { get; set; }
}

using McpServer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    // Register a named HttpClient for WeatherTools (IHttpClientFactory pattern)
    .AddHttpClient<WeatherTools>(client =>
    {
        client.DefaultRequestHeaders.UserAgent.ParseAdd("McpWeatherServer/1.0");
    });

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()       // stdio transport for CLI/editor integration
    .WithToolsFromAssembly();         // discovers all [McpServerTool] methods

await builder.Build().RunAsync();

